    }
}

func resetLine(_ u: Double, _ iso: String?, _ samples: [HistorySample], _ now: Date) -> String {
    let r = parseISO(iso)
    if r == nil {
        return "No active 5-hour window — starts on your next Claude request"
    } else if r! <= now {
        return "Window just reset — refreshing soon"
    } else {
        let c = formatClock(r!)
        let mins = max(0.0, r!.timeIntervalSince(now) / 60.0)
        if u >= cappedAt {
            let m = Int(mins)
            let w = hoursMinutes(m)
            return "Capped — resets in \(w) (@ \(c))"
        } else {
            let v = valid(samples)
            let recent = Array(v.suffix(burnWindow))
            let n = recent.count
            if n < 3 {
                return "Resets @ \(c) · click to refresh"
            } else {
                let (pp, sec) = burn(recent, 1, 0.0, 0.0)
                let rate: Double
                if sec > 0.0 {
                    rate = (pp / sec) * 3600.0
                } else {
                    rate = 0.0
                }
                if rate < idleBelow {
                    if sec < (pollInterval * 2.0) {
                        return "Resets @ \(c) · measuring…"
                    } else {
                        return "Resets @ \(c) · idle"
                    }
                } else {
                    let left = max(0.0, 100.0 - u)
                    let safe: Double
                    if mins > 0.0 {
                        safe = (left / mins) * 60.0
                    } else {
                        safe = 0.0
                    }
                    let b = Int(rate.rounded())
                    let sf = max(0, Int(safe.rounded()))
                    if rate > (safe * paceBuffer) {
                        let to100 = Int((left / rate) * 60.0)
                        let w = hoursMinutes(to100)
                        return "Resets @ \(c) · \(b)%/h over safe \(sf)%/h · 100% in \(w)"
                    } else {
                        return "Resets @ \(c) · \(b)%/h · safe ≤ \(sf)%/h"
                    }
                }
            }
        }
    }
}

