        let tmp4 = r[j]
        let d = tmp3.utilization - tmp4.utilization
        let dt = tmp3.timestamp.timeIntervalSince(tmp4.timestamp)
        let per: Double
        if (d > 0.0) && (dt > 0.0) {
            per = (d / dt) * pollInterval
        } else {
            per = 0.0
        }
        let l = min(7, max(0, Int(((max(0.0, min(per, 3.0)) / 3.0) * 7.0).rounded())))
        let c = bar(l)
        let i1 = i + 1
        let rest = bars(r, i1)
        return c + rest
    }
}

