        let vs = zeroed(Array(a1.dropFirst()))
        return [v] + vs
    }
    fatalError("unreachable")
}

func smooth(_ z: [Double], _ i: Int, _ n: Int) -> [Double] {
    if i >= n {
        return []
    } else {
        let lo = max(0, i - 1)
        let hi = min(n - 1, i + 1)
        let sum = sumFrom(z, lo, hi, 0.0)
        let a = sum / Double((hi - lo) + 1)
        let i1 = i + 1
        let rest = smooth(z, i1, n)
        return [a] + rest
    }
}

func sumFrom(_ z: [Double], _ i: Int, _ hi: Int, _ acc: Double) -> Double {
    if i > hi {
        return acc
    } else {
        let v = z[i]
        let acc1 = acc + v
        let i1 = i + 1
        return sumFrom(z, i1, hi, acc1)
    }
}

func waveFrame(_ step: Int) -> String {
    let p = step % 18
    let i: Int
    if p < 10 {
        i = p
    } else {
        i = 18 - p
    }
    return waveCells(i, 0)
}

func waveCells(_ i: Int, _ j: Int) -> String {
    if j >= 10 {
        return ""
    } else {
        let l = max(0, 7 - abs(i - j))
        let c = bar(l)
        let j1 = j + 1
        let r = waveCells(i, j1)
        return c + r
    }
}

func errorFrame(_ f: Int, _ msg: String, _ width: Int) -> String? {
    let cycle = 18 + marqueeFrames
    if f >= (errorCycles * cycle) {
        return nil
    } else {
        let p = f % cycle
        if p < 18 {
            return waveFrame(p)
        } else {
            let pad = String(repeating: " ", count: width)
            let a = pad + msg
            let all = a + "    "
            let len = all.count
            let start = Int(Double(p - 18) * marqueeSpeed) % len
            return window(all, start, width, len)
        }
    }
}

func window(_ s: String, _ start: Int, _ n: Int, _ len: Int) -> String {
    if n <= 0 {
        return ""
    } else {
        let i = start % len
        let c = String(Array(s)[i])
        let next = start + 1
        let n1 = n - 1
        let rest = window(s, next, n1, len)
        return c + rest
    }
}

