func rollover(_ lastU: Double?, _ u: Double, _ lastR: String?, _ r: String?, _ now: Date) -> Bool {
    let d = parseISO(r)
    if lastU == nil {
        return false
    } else if lastU! < 0.0 {
        return false
    } else if d == nil {
        return false
    } else if d! <= now {
        return false
    } else if (lastR != nil) && (lastR! != r) {
        return true
    } else if lastU! > (u + bigDrop) {
        return true
    } else {
        return false
    }
}

func shouldPoll(_ until: Date?, _ last: Date?, _ now: Date) -> Bool {
    if (until != nil) && (until! > now) {
        return false
    } else if (last != nil) && (now.timeIntervalSince(last!) < (pollInterval / 2.0)) {
        return false
    } else {
        return true
    }
}

func coolingDown(_ last: Date?, _ now: Date) -> Bool {
    if (last != nil) && (now.timeIntervalSince(last!) < clickCooldown) {
        return true
    } else {
        return false
    }
}

func clickEffect(_ until: Date?, _ last: Date?, _ now: Date) -> Click {
    let cool = coolingDown(last, now)
    if (until != nil) && (until! > now) {
        return Click.blocked
    } else if cool == true {
        return Click.cooling
    } else {
        return Click.fetch
    }
}

func backoffSecs(_ count: Int, _ retry: Double?) -> Double {
    let e = min(backoffBase * pow(2.0, Double(count - 1)), backoffCap)
    if retry == nil {
        return e
    } else {
        return max(retry!, e)
    }
}

func crossed(_ u: Double, _ fired: [Int]) -> [Int] {
