}

func crossedFrom(_ a1: [Int], _ u: Double, _ fired: [Int]) -> [Int] {
    if a1.isEmpty {
        return []
    }
    if !(a1.isEmpty) {
        let rest = crossedFrom(Array(a1.dropFirst()), u, fired)
        if (u >= Double(a1[0])) && !(fired.contains(a1[0])) {
            return [a1[0]] + rest
        } else {
            return rest
        }
    }
    fatalError("unreachable")
}

