func statusLine(_ e: AppError?, _ last: Date?, _ until: Date?, _ next: Date?, _ now: Date) -> String {
    let prefix: String
    if e == nil {
        prefix = ""
    } else if e!.kind == .rateLimited {
        prefix = "rate-limited · "
    } else {
        let sym = errorSymbol(e!)
        prefix = "\(sym) · "
    }
    let seen: String
    if last == nil {
        seen = "never"
    } else {
        seen = relativeTime(last!, now)
    }
    let tail: String
    if (e != nil) && (e!.kind == .rateLimited && (until != nil)) {
        let w = max(0, Int(until!.timeIntervalSince(now)))
        let a = nextAttempt(w)
        tail = "next in \(a)"
    } else if last == nil {
        tail = "click to refresh"
    } else if next != nil {
        let w = max(0, Int(next!.timeIntervalSince(now)))
        if w <= 0 {
            tail = "next now…"
        } else if w < 60 {
            tail = "next in \(w)s"
        } else {
            let m = w / 60
            let r = w % 60
            tail = "next in \(m)m \(r)s"
        }
    } else {
        tail = "—"
    }
    return "\(prefix)Last updated: \(seen) · \(tail)"
}

