    fatalError("unreachable")
}

func newer(_ l: [Int], _ c: [Int]) -> Bool {
    if l.isEmpty, c.isEmpty {
        return false
    }
    let (a, lt) = head0(l)
    let (b, ct) = head0(c)
    if a > b {
        return true
    } else if a < b {
        return false
    } else {
        return newer(lt, ct)
    }
}

func head0(_ a1: [Int]) -> (Int, [Int]) {
    if a1.isEmpty {
        return (0, [])
    }
    if !(a1.isEmpty) {
        return (a1[0], Array(a1.dropFirst()))
    }
    fatalError("unreachable")
}

func rawToken(_ text: String) -> String? {
    let t = text.trimmingCharacters(in: .whitespacesAndNewlines)
    if (t != "") && (!(t.contains(" ")) && (!(t.contains("\n")) && t.hasPrefix("sk-"))) {
        return t
    } else {
        return nil
    }
}

func titleParts(_ showP: Bool, _ showW: Bool, _ showR: Bool, _ p: String, _ w: String, _ r: String?) -> [Part] {
    let a: [Part]
    if showP == true {
        a = [Part.pct(p)]
    } else {
        a = []
    }
    let b: [Part]
    if showW == true {
        b = [Part.spark(w)]
    } else {
        b = []
    }
    let c: [Part]
    if (showR == true) && (r != nil) {
        c = [Part.reset(r!)]
    } else {
        c = []
    }
    let aB = a + b
    return aB + c
}

func menuRows(_ e: AppError?, _ r: UsageResponse?) -> [Row] {
    let top: [Row]
    if (e != nil) && e!.kind == .tokenNotFound {
        top = [Row.status, Row.action("→ Open Settings", MenuAction.openSettings), Row.separator]
    } else {
        top = [Row.status, Row.separator]
    }
    let body: [Row]
    if r == nil {
        body = []
    } else {
        let reset: [Row]
        if r!.fiveHour == nil {
            reset = []
        } else {
            reset = [Row.reset]
        }
        let w = weeklyRows(r!)
        let weekly: [Row]
        if w.isEmpty {
            weekly = []
        } else {
            weekly = [Row.separator, Row.header("Weekly limits")] + w
        }
        let credits = creditsRows(r!.extraUsage)
        let b1 = reset + weekly
        body = b1 + credits
    }
    let t1 = top + body
    return t1 + [Row.separator, Row.action("Refresh now", MenuAction.refresh), Row.action("Open claude.ai/settings/usage", MenuAction.openUsage), Row.action("Settings…", MenuAction.openSettings), Row.separator, Row.action("Quit claude-limits", MenuAction.quit)]
}

func creditsRows(_ x: ExtraUsage?) -> [Row] {
    if x == nil {
        return []
    } else if x!.isEnabled == true {
        let u = (x!.usedCredits ?? 0.0)
        let l = (x!.monthlyLimit ?? 0.0)
        let c = (x!.currency ?? "USD")
        let t = creditsText(u, l, c)
        return [Row.separator, Row.pair("Pay-as-you-go credits", t)]
    } else {
        return []
    }
}

func weeklyRows(_ r: UsageResponse) -> [Row] {
    let legacy = bucketRows(["Overall", "Opus", "Sonnet", "OAuth apps", "Cowork", "Claude Design"], [r.sevenDay, r.sevenDayOpus, r.sevenDaySonnet, r.sevenDayOauthApps, r.sevenDayCowork, r.sevenDayOmelette])
    if !(legacy.isEmpty) {
        return legacy
    } else {
        let l = (r.limits ?? [])
        return limitRows(l)
    }
}

func bucketRows(_ a1: [String], _ a2: [UsageBucket?]) -> [Row] {
    if a1.isEmpty, a2.isEmpty {
        return []
    }
    if !(a1.isEmpty), !(a2.isEmpty) {
        let rest = bucketRows(Array(a1.dropFirst()), Array(a2.dropFirst()))
        if a2[0] == nil {
            return rest
        } else {
            let row = barRow(a1[0], a2[0]!.utilization)
            return [row] + rest
        }
    }
    fatalError("unreachable")
}

func limitRows(_ a1: [UsageLimit]) -> [Row] {
    if a1.isEmpty {
        return []
    }
    if !(a1.isEmpty) {
        let rest = limitRows(Array(a1.dropFirst()))
        if (a1[0].group == "weekly") && (a1[0].percent != nil) {
            let n = scopeName(a1[0].scope)
            let row = barRow(n, a1[0].percent!)
            return [row] + rest
        } else {
            return rest
        }
    }
    fatalError("unreachable")
}

func scopeName(_ s: LimitScope?) -> String {
    if s == nil {
        return "Overall"
    } else if s!.model == nil {
        return "Overall"
    } else {
        return (s!.model!.displayName ?? "Overall")
    }
}

func barRow(_ label: String, _ u: Double) -> Row {
    let p = percent(u)
    let v = "\(p)%"
    return Row.bar(label, u, v)
}

func iconLevel(_ u: Double) -> Int {
    if u >= 95.0 {
        return 2
    } else if u >= 80.0 {
        return 1
    } else {
        return 0
    }
}

func trayText(_ n: Int?, _ err: Bool, _ plain: String?) -> String? {
    if n != nil {
        return "\(n!)"
    } else if err == true {
        return "!"
    } else if plain == "—" {
        return "–"
    } else {
        return nil
    }
}

func trayLevel(_ n: Int?, _ u: Double, _ err: Bool) -> Int {
    if n != nil {
        return iconLevel(u)
    } else if err == true {
        return 3
    } else {
        return 0
    }
}

func tooltip(_ u: Double?, _ iso: String?, _ e: AppError?, _ now: Date) -> String {
    let s2: String
    if u != nil {
        let p = Int(u!.rounded())
        let s0 = "claude-limits · \(p)%"
        let r = countdown(iso, now)
        let s1: String
        if r == nil {
            s1 = s0
        } else {
            s1 = "\(s0) · resets in \(r!)"
        }
        if e == nil {
            s2 = s1
        } else {
            let sym = errorSymbol(e!)
            s2 = "\(s1) · \(sym)"
        }
    } else if e != nil {
        let sym = errorSymbol(e!)
        s2 = "claude-limits · \(sym)"
    } else {
        s2 = "claude-limits"
    }
    let n = s2.count
    if n > 63 {
        let h = String(s2.prefix(62))
        return h + "…"
    } else {
        return s2
    }
}

func dotOnOpen(_ have: Bool, _ last: Date?, _ busy: Bool, _ until: Date?, _ click: Date?, _ now: Date) -> Dot {
    let cool = coolingDown(click, now)
    if have == true {
        return Dot.connected
    } else if (last != nil) && (now.timeIntervalSince(last!) < pollInterval) {
        return Dot.connected
    } else if busy == true {
        return Dot.unverified
    } else if (until != nil) && (until! > now) {
        return Dot.unverified
    } else if cool == true {
        return Dot.unverified
    } else {
        return Dot.probe
    }
}

func updateStatus(_ latest: String?, _ err: String?, _ ver: String) -> String {
    if err != nil {
        return "Couldn't reach GitHub: \(err!)"
    } else if latest != nil {
        return "Update \(latest!) available — click “Update to \(latest!)”."
    } else {
        return "You're on the latest version (v\(ver))."
    }
}

func updateButton(_ l: String?) -> String {
    if l == nil {
        return "Check for updates"
    } else {
        return "Update to \(l!)"
    }
}

func updatingStatus(_ v: String) -> String {
    return "Updating to \(v)… the app will relaunch when done."
}

func updatingNotice(_ v: String, _ w: String) -> String {
    return "Installing \(v) — the \(w) will return in a few seconds."
}

func testStatus(_ u: Double?) -> String {
    if u == nil {
        return "Connected, but no five_hour data."
    } else {
        let p = Int(u!.rounded())
        return "OK — current session at \(p)%"
    }
}

func waitStatus(_ n: Int) -> String {
    return "Rate limited — wait \(n)s before testing again."
}
